contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner) public {
        address originalOwner = c.owner();
        bool reverted;
        bytes memory callData = abi.encodeWithSignature("setOwner(address)", newOwner);
        (bool success, bytes memory returnData) = address(c).call(callData);
        if (!success) {
            reverted = true;
        } else {
            reverted = false;
            require(returnData.length == 32);
            bool returned = abi.decode(returnData, (bool));
            assert(returned == true);
        }
        address currentOwner = c.owner();
        if (msg.sender == originalOwner) {
            assert(!reverted && currentOwner == newOwner);
        } else {
            assert(reverted && currentOwner == originalOwner);
        }
    }
}

